    var screenshotWidth = captureSource && captureSource.width ? captureSource.width : 0;
    var screenshotHeight = captureSource && captureSource.height ? captureSource.height : 0;
    if (perf) perf.screenshotSize = { width: screenshotWidth, height: screenshotHeight };

    var scale = screenshotWidth / viewportRect.width;
    if (!(scale > 0)) scale = screenshotHeight / viewportRect.height;
    if (!(scale > 0)) scale = 1;

    var effectiveFocusRect = visibleFocusRect || focusRect;
    var focusRight = effectiveFocusRect ? effectiveFocusRect.left + effectiveFocusRect.width : 0;
    var focusBottom = effectiveFocusRect ? effectiveFocusRect.top + effectiveFocusRect.height : 0;
    var shotRight = rect.left + rect.width;
    var shotBottom = rect.top + rect.height;
    var focusContainsShot = !!(effectiveFocusRect && rectContainsRect(effectiveFocusRect, rect));
