      sourceBounds.left,
      sourceBounds.top,
      sourceBounds.width,
      sourceBounds.height,
      Math.round(destBounds.left * recordSourceScale),
      Math.round(destBounds.top * recordSourceScale),
      Math.max(1, Math.round(destBounds.width * recordSourceScale)),
      Math.max(1, Math.round(destBounds.height * recordSourceScale))
