    var b = num(box.b);
    var l = num(box.l);
    var values = [
      { side: "top", value: t },
      { side: "right", value: r },
      { side: "bottom", value: b },
      { side: "left", value: l }
    ];
    var nonZero = values.filter(function (item) {
      return item.value !== 0;
    });
